//! 🔺️ create-sampler leaf-owned typed sparse operation diff.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfSampler;
use crate::artifacts::gltf::schema::diff::GltfDiff;
use crate::artifacts::gltf::schema::mutations::create_sampler::mutation::{apply, validate, GltfCreateSamplerPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{samplers_op, family_diff, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-sampler.v1";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateSamplerOperation { Insert { position: usize, item: GltfSampler }, Delete { index: usize, removed: GltfSampler }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateSamplerDiff { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateSamplerPayload, pub operation: GltfCreateSamplerOperation }
fn operation(payload: &GltfCreateSamplerPayload, base: &GltfSnapshot) -> GltfCreateSamplerOperation { GltfCreateSamplerOperation::Insert { position: payload.position, item: GltfSampler::default() } }
fn touched_paths(payload: &GltfCreateSamplerPayload) -> Vec<String> { vec![format!("document/samplers/{}", payload.position)] }
pub fn validate_diff(diff: &GltfCreateSamplerDiff, base: &GltfSnapshot) -> Result<(), GltfTopLevelMutationRejection> { if diff.id != ID || diff.version != 1 { return Err(reject("gltf.mutation.invalid-diff-envelope", "diff", "descriptor identity does not match")); } if diff.touched_paths != touched_paths(&diff.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "diff/touchedPaths", "paths must be concrete payload-derived locations")); } validate(&diff.payload, base)?; if diff.operation != operation(&diff.payload, base) { return Err(reject("gltf.mutation.invalid-sparse-operation", "diff/operation", "operation must equal the direct typed delta")); } Ok(()) }
pub fn apply_diff(diff: &GltfCreateSamplerDiff, base: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_diff(diff, base)?; let mut next = base.clone(); let operation = &diff.operation; match operation { GltfCreateSamplerOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Samplers, &Change::Insert(*position))?; next.document.samplers.insert(*position, item.clone());  }, GltfCreateSamplerOperation::Delete { index, .. } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, *index, None, None)?;  }, GltfCreateSamplerOperation::Move { index, position } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, *index, Some(*position), None)?;  }, GltfCreateSamplerOperation::Reorder { order } => { samplers_op(&mut next, GltfTopLevelFamily::Samplers, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(diff: &GltfCreateSamplerDiff) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(diff).map_err(|error| reject("gltf.mutation.encode-failed", "diff", error.to_string())) }
pub fn derive(payload: &GltfCreateSamplerPayload, base: &GltfSnapshot) -> Result<GltfCreateSamplerDiff, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateSamplerDiff { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
pub fn derive_transitional_gltf_diff(payload: &GltfCreateSamplerPayload, base: &GltfSnapshot) -> Result<GltfDiff, GltfTopLevelMutationRejection> { let next = apply(payload, base)?; Ok(family_diff(GltfTopLevelFamily::Samplers, base, &next)) }
